import java.util.Scanner;public class RadixConverter {    public static void main(String[] args) {        Scanner scanner = new Scanner(System.in);        String continueChoice;        do {            System.out.println("\n=== Base Converter ===");            System.out.println("Select your INPUT format:");            System.out.println("1 - Binary");            System.out.println("2 - Octal");            System.out.println("3 - Decimal");            System.out.println("4 - Hexadecimal");            System.out.print("Enter choice (1-4): ");            int inputChoice = scanner.nextInt();            int fromBase = getBaseFromChoice(inputChoice);            System.out.print("\nEnter your value: ");            scanner.nextLine();            String rawInput = scanner.nextLine().trim();            String cleanInput = rawInput.replaceAll("\\s+", "");            System.out.println("\nSelect TARGET conversion format:");            System.out.println("1 - Binary");            System.out.println("2 - Octal");            System.out.println("3 - Decimal");            System.out.println("4 - Hexadecimal");            System.out.print("Enter choice (1-4): ");            int targetChoice = scanner.nextInt();            int toBase = getBaseFromChoice(targetChoice);            try {                int decimalValue = Integer.parseInt(cleanInput, fromBase);                String result = Integer.toString(decimalValue, toBase).toUpperCase();                System.out.println("\n----------------------------------");                System.out.printf("Converted Result: %s\n", result);                System.out.println("----------------------------------");            } catch (NumberFormatException e) {                System.out.println("\nError: '" + rawInput + "' contains invalid digits for the selected input base.");            }            System.out.print("\nDo you want to perform another conversion? (Y/N): ");            continueChoice = scanner.next().trim();        } while (continueChoice.equalsIgnoreCase("Y"));        System.out.println("\nThank you for using Base Converter! Program terminated.");        scanner.close();    }    private static int getBaseFromChoice(int choice) {        return switch (choice) {            case 1 -> 2;            case 2 -> 8;              case 3 -> 10;             case 4 -> 16;             default -> 10;        };    }}